window.WOMENS_FORMULAS_DATA = {"note":"Practitioner-line women's hormone formulas, transcribed from Nourhan Shams's own compiled list. The brand, the formula and what it contains are hers; the caution on each entry was written for this tool.","targets":[{"id":"phase12","label":"Phase I/II estrogen metabolism"},{"id":"luteal","label":"Luteal & progesterone support"},{"id":"ovarian","label":"Ovarian & glycemic signalling (PCOS)"},{"id":"vasomotor","label":"Neuroendocrine & vasomotor (perimenopause, menopause)"},{"id":"precursor","label":"Steroid precursors"},{"id":"estrobolome","label":"Estrobolome & microbiome"},{"id":"adrenal","label":"Adrenal–ovarian axis"},{"id":"hepatic","label":"Hepatic conjugation support"}],"bases":[{"id":"nutrient","label":"Nutrient"},{"id":"botanical","label":"Botanical"},{"id":"mixed","label":"Botanical + nutrient"},{"id":"hormone","label":"Hormone precursor"},{"id":"probiotic","label":"Probiotic"}],"brands":["Thorne","Pure Encapsulations","Ortho Molecular","Metagenics","Integrative Therapeutics","Designs for Health","Xymogen","Klaire Labs","Seeking Health","Gaia Herbs"],"formulas":[{"id":"thorne_hormone_advantage","brand":"Thorne","name":"Hormone Advantage","target":"phase12","base":"mixed","actives":"Diindolylmethane (DIM), sulforaphane glucosinolate from broccoli seed extract, pomegranate extract","what":"Estrogen metabolism. Favours the protective 2-hydroxyestrone pathway.","caution":"DIM can darken the urine and provoke headache. It induces CYP1A2, so check any narrow-therapeutic-index drug the patient takes. Not for use in pregnancy or lactation.","conditions":["Premenstrual syndrome","Endometriosis"],"also":"formerly DIM Advantage"},{"id":"thorne_ovarian_care","brand":"Thorne","name":"Ovarian Care","target":"ovarian","base":"nutrient","actives":"Myo-inositol and D-chiro-inositol in a 40:1 ratio, CoQ10 phytosome, polyphenols, 5-MTHF","what":"Powder. Ovulatory support and insulin sensitivity at the physiological inositol ratio.","caution":"Inositol at gram doses commonly causes loose stools and nausea; divide the dose. Watch for hypoglycaemia if it is combined with metformin or an insulin secretagogue.","conditions":["Polycystic ovary syndrome","Fertility and preconception"],"also":null},{"id":"thorne_meta_balance","brand":"Thorne","name":"Meta-Balance","target":"vasomotor","base":"botanical","actives":"Vitex agnus-castus, black cohosh, wild yam, maritime pine bark (Pycnogenol)","what":"Hot flushes, cycle irregularity and tissue elasticity through the menopausal transition.","caution":"Black cohosh carries rare idiosyncratic hepatotoxicity reports — avoid in liver disease and stop for any jaundice, dark urine or right-upper-quadrant pain. Vitex is dopaminergic: avoid alongside dopamine agonists or antagonists, and in anyone on fertility drugs or hormonal contraception. Wild yam is not a progesterone precursor in the body, whatever the label implies.","conditions":["Menopause"],"also":null},{"id":"thorne_pregnenolone","brand":"Thorne","name":"Pregnenolone","target":"precursor","base":"hormone","actives":"Pregnenolone","what":"Upstream steroidogenesis support.","caution":"A hormone, not a nutrient. Unpredictable downstream conversion to androgens and estrogens; contraindicated in hormone-sensitive cancer, and unstudied in pregnancy. Whether you may prescribe it varies by jurisdiction — check your scope, and monitor.","conditions":[],"also":null},{"id":"thorne_dhea","brand":"Thorne","name":"DHEA (5 mg and 25 mg)","target":"precursor","base":"hormone","actives":"Dehydroepiandrosterone","what":"Upstream adrenal and ovarian steroid support at two strengths.","caution":"A hormone. Androgenic effects — acne, hirsutism, hair loss, voice change — and suppression of endogenous production. Contraindicated in hormone-sensitive cancer and in PCOS with existing hyperandrogenism. Banned in most sport. Baseline and follow-up DHEA-S is the minimum monitoring.","conditions":[],"also":null},{"id":"pure_dim_detox","brand":"Pure Encapsulations","name":"DIM Detox","target":"phase12","base":"mixed","actives":"BioResponse microencapsulated DIM, calcium-D-glucarate, sulforaphane, alpha-lipoic acid, NAC, amino acids","what":"Pairs Phase II glucuronidation with glutathione conjugation rather than driving Phase I alone.","caution":"Alpha-lipoic acid lowers blood glucose and can unmask hypoglycaemia on insulin or a sulfonylurea. NAC occasionally causes nausea and, rarely, bronchospasm. Not in pregnancy or lactation.","conditions":["Premenstrual syndrome","Endometriosis"],"also":null},{"id":"pure_dim_pro","brand":"Pure Encapsulations","name":"DIM-Pro 100","target":"phase12","base":"nutrient","actives":"Diindolylmethane 100 mg, microencapsulated","what":"Single-entity DIM where a formula would be redundant.","caution":"As for any DIM: CYP1A2 induction, darkened urine, headache. Not in pregnancy or lactation.","conditions":[],"also":null},{"id":"pure_chaste_tree","brand":"Pure Encapsulations","name":"Chaste Tree (Vitex)","target":"luteal","base":"botanical","actives":"Vitex agnus-castus fruit extract, standardised, 225 mg","what":"Dopaminergic modulation at the pituitary; luteal phase support and cycle regularity.","caution":"Dopaminergic — do not combine with dopamine agonists or antagonists, including metoclopramide and antipsychotics. May interfere with hormonal contraception and with fertility treatment. Stop in pregnancy.","conditions":["Premenstrual syndrome","Amenorrhea","Fertility and preconception"],"also":null},{"id":"pure_prosoothe","brand":"Pure Encapsulations","name":"ProSoothe","target":"luteal","base":"mixed","actives":"Botanical and nutrient blend for the premenstrual phase","what":"Cyclical breast tenderness and premenstrual mood shifts.","caution":"Check the current label before dispensing — the composition of premenstrual blends changes between revisions, and the interaction profile changes with it.","conditions":["Premenstrual syndrome"],"also":null},{"id":"pure_menopause_support","brand":"Pure Encapsulations","name":"Menopause Support","target":"vasomotor","base":"botanical","actives":"Black cohosh, red clover isoflavones, rhodiola","what":"Vasomotor symptoms with a stimulating adaptogen for the fatigue that accompanies them.","caution":"Red clover isoflavones are phytoestrogens — avoid in estrogen-receptor-positive disease and discuss with the oncologist in any breast cancer history. Black cohosh: rare hepatotoxicity. Rhodiola is stimulating and can destabilise bipolar disorder or disturb sleep if taken late.","conditions":["Menopause"],"also":null},{"id":"pure_black_cohosh","brand":"Pure Encapsulations","name":"Black Cohosh 2.5","target":"vasomotor","base":"botanical","actives":"Actaea racemosa, standardised to 2.5% triterpene glycosides","what":"Isolated black cohosh where the rest of a menopause formula is not wanted.","caution":"Rare idiosyncratic hepatotoxicity — avoid in liver disease, and stop for jaundice, dark urine or right-upper-quadrant pain. Not for undiagnosed abnormal uterine bleeding.","conditions":["Menopause"],"also":null},{"id":"pure_inositol","brand":"Pure Encapsulations","name":"Inositol (capsules and powder)","target":"ovarian","base":"nutrient","actives":"Myo-inositol","what":"Single-nutrient inositol for ovarian and glycaemic signalling.","caution":"Loose stools and nausea at gram doses. Divide the dose and titrate.","conditions":["Polycystic ovary syndrome"],"also":null},{"id":"pure_dhea","brand":"Pure Encapsulations","name":"DHEA","target":"precursor","base":"hormone","actives":"Dehydroepiandrosterone","what":"Bioidentical DHEA.","caution":"A hormone — the same cautions as any DHEA: androgenic effects, suppression of endogenous production, contraindicated in hormone-sensitive cancer. Monitor DHEA-S.","conditions":[],"also":null},{"id":"ortho_estrodim","brand":"Ortho Molecular","name":"EstroDIM","target":"phase12","base":"nutrient","actives":"Indole-3-carbinol 200 mg with diindolylmethane 100 mg","what":"Drives CYP1A1 activity toward the protective 2-OHE1 metabolites.","caution":"I3C converts to DIM and other condensation products in stomach acid, so the delivered dose varies with gastric pH — an acid suppressant changes what the patient actually absorbs. Not in pregnancy.","conditions":["Endometriosis","Premenstrual syndrome"],"also":null},{"id":"ortho_dhist","brand":"Ortho Molecular","name":"Natural D-Hist","target":"phase12","base":"mixed","actives":"Quercetin, stinging nettle leaf, bromelain, NAC, vitamin C","what":"Used in the luteal phase, where the estrogen peak triggers mast-cell degranulation and histamine-driven headache — the estrogen–gut–histamine axis.","caution":"Bromelain has antiplatelet activity: stop before surgery and take care alongside an anticoagulant. Quercetin inhibits CYP3A4. The estrogen–histamine link is a plausible mechanism, not a settled one.","conditions":["Migraine","Premenstrual syndrome"],"also":null},{"id":"ortho_inositol","brand":"Ortho Molecular","name":"Inositol Powder","target":"ovarian","base":"nutrient","actives":"High-purity myo-inositol","what":"High-gram dosing for follicular fluid quality, LH/FSH ratio and peripheral insulin receptor sensitivity.","caution":"Gastrointestinal upset is dose-limiting. Watch glucose if it is added to metformin.","conditions":["Polycystic ovary syndrome","Fertility and preconception"],"also":null},{"id":"ortho_dhea","brand":"Ortho Molecular","name":"Micronized DHEA (sublingual and capsule)","target":"precursor","base":"hormone","actives":"Micronized dehydroepiandrosterone","what":"Steroid precursor in two delivery forms.","caution":"A hormone. Sublingual delivery bypasses first-pass metabolism, so the same milligram figure is not the same exposure as a capsule — do not swap forms at the same dose. Monitor DHEA-S.","conditions":[],"also":null},{"id":"ortho_pregnenolone","brand":"Ortho Molecular","name":"Pregnenolone","target":"precursor","base":"hormone","actives":"Pregnenolone","what":"Steroid precursor.","caution":"A hormone, with unpredictable conversion downstream. Contraindicated in hormone-sensitive cancer.","conditions":[],"also":null},{"id":"meta_estrovera","brand":"Metagenics","name":"Estrovera","target":"vasomotor","base":"botanical","actives":"ERr 731, a standardised extract of Siberian rhubarb (Rheum rhaponticum)","what":"Metagenics' flagship women's product. Acts as a selective estrogen receptor-beta agonist for hot flushes, sleep disruption and mood volatility.","caution":"The best-studied non-hormonal option on this list, with its own randomised trials — but still an estrogen-receptor agonist. Discuss it with the oncologist in any estrogen-receptor-positive history, and do not use it in undiagnosed abnormal uterine bleeding.","conditions":["Menopause"],"also":null},{"id":"meta_estrofactors","brand":"Metagenics","name":"EstroFactors","target":"phase12","base":"mixed","actives":"BioResponse DIM, calcium-D-glucarate, methylated B vitamins, rosemary extract, isoxanthohumol from hops","what":"Hydroxylation and methylation together — Phase I direction plus the methyl donors Phase II needs.","caution":"Isoxanthohumol is a hop prenylflavonoid that converts to the potent phytoestrogen 8-prenylnaringenin in some people's gut flora; the estrogenic exposure is therefore not predictable from the label.","conditions":["Premenstrual syndrome"],"also":null},{"id":"meta_chasteberry_plus","brand":"Metagenics","name":"Chasteberry Plus","target":"luteal","base":"botanical","actives":"Standardised Vitex agnus-castus with black cohosh and ashwagandha","what":"Corpus luteum function, and the HPA–HPG stress-hormone cross-talk behind it.","caution":"Vitex is dopaminergic (see Chaste Tree). Black cohosh: rare hepatotoxicity. Ashwagandha raises thyroid hormones — avoid in hyperthyroidism — and is a nightshade.","conditions":["Premenstrual syndrome","Amenorrhea"],"also":null},{"id":"int_indolplex","brand":"Integrative Therapeutics","name":"Indolplex","target":"phase12","base":"nutrient","actives":"BR-DIM, bioavailable microencapsulated diindolylmethane","what":"The extensively studied absorbable DIM form; improves the 2-OHE1 to 16α-OHE1 ratio.","caution":"As for any DIM. The metabolite ratio is a surrogate marker, not an outcome.","conditions":[],"also":null},{"id":"int_fem_premenstrual","brand":"Integrative Therapeutics","name":"Fem Premenstrual","target":"luteal","base":"mixed","actives":"Botanical extracts with active vitamin B6 (pyridoxal-5-phosphate)","what":"Premenstrual fluid balance, cramping and mood stability.","caution":"Pyridoxine above roughly 100 mg daily, taken chronically, causes a sensory peripheral neuropathy that is only partly reversible — total the B6 across everything the patient takes.","conditions":["Premenstrual syndrome","Dysmenorrhea"],"also":null},{"id":"int_ampm_perimenopause","brand":"Integrative Therapeutics","name":"AM/PM PeriMenopause Formula","target":"vasomotor","base":"botanical","actives":"Daytime: black cohosh, green tea, Korean ginseng. Nighttime: black cohosh, valerian, L-theanine","what":"Splits the symptom picture in two — an energising daytime blend and a restorative nighttime one.","caution":"Green tea extract has been associated with idiosyncratic hepatotoxicity at concentrated doses; with black cohosh in the same capsule, any liver-enzyme rise needs both stopped. Korean ginseng is stimulating — caution in hypertension and bipolar disorder.","conditions":["Menopause","Insomnia"],"also":null},{"id":"int_cortisol_manager","brand":"Integrative Therapeutics","name":"Cortisol Manager","target":"adrenal","base":"mixed","actives":"Ashwagandha, L-theanine, magnolia and phosphatidylserine","what":"Used clinically to suppress nocturnal hypercortisolaemia and, on the functional-medicine model, to prevent “progesterone steal”.","caution":"Sedating — dose at night, and warn about driving. Ashwagandha raises thyroid hormones and is contraindicated in hyperthyroidism. Note that “pregnenolone steal” is a widely repeated model with little physiological support: steroidogenesis is compartmentalised by tissue, not drawn from a shared pool.","conditions":["Insomnia"],"also":null},{"id":"dfh_femguard","brand":"Designs for Health","name":"FemGuard + Balance","target":"phase12","base":"mixed","actives":"DIM, chrysin, calcium-D-glucarate, Vitex, black cohosh, TrueBroc broccoli extract, trans-resveratrol","what":"The full-spectrum entry on this list: estrogen metabolism and cycle regularity in one formula.","caution":"Seven actives means seven interaction profiles — chrysin as an aromatase inhibitor, Vitex as a dopaminergic, black cohosh with its hepatic signal. Chrysin's oral bioavailability is very poor, so the aromatase claim is largely theoretical. Not in pregnancy.","conditions":["Premenstrual syndrome","Endometriosis"],"also":null},{"id":"dfh_progest_avail","brand":"Designs for Health","name":"Progest-Avail","target":"luteal","base":"hormone","actives":"Topical bioidentical progesterone, micronized, derived from wild yam","what":"A topical progesterone serum without synthetic preservatives or mineral oils.","caution":"This is a hormone, not a herb — the wild yam is only the synthetic starting material. Transdermal progesterone does not read reliably in serum, so do not titrate it against a blood level. Unopposed use, and use in anyone with a history of hormone-sensitive cancer, needs a prescriber. Regulatory status varies by jurisdiction; check your scope.","conditions":["Menopause","Premenstrual syndrome"],"also":null},{"id":"dfh_sensitol","brand":"Designs for Health","name":"Sensitol (and OVO-Evail)","target":"ovarian","base":"nutrient","actives":"Myo-inositol and D-chiro-inositol 40:1 with alpha-lipoic acid","what":"The physiological inositol ratio with ALA for insulin signalling.","caution":"ALA lowers blood glucose — watch for hypoglycaemia on insulin or a secretagogue. Inositol at gram doses loosens the stool.","conditions":["Polycystic ovary syndrome"],"also":null},{"id":"dfh_dim_evail","brand":"Designs for Health","name":"DIM-Evail","target":"phase12","base":"nutrient","actives":"DIM in a self-emulsifying softgel with medium-chain triglycerides and quillaja extract","what":"A delivery answer to DIM's poor lipid absorption.","caution":"Better absorption means a lower milligram figure is not a lower exposure — do not read this dose against a plain-powder dose.","conditions":[],"also":null},{"id":"xym_femquil","brand":"Xymogen","name":"Femquil","target":"phase12","base":"mixed","actives":"Calcium-D-glucarate, DIM, chrysin, black cohosh, Vitex, green tea extract, Quatrefolic methylfolate","what":"Xymogen's flagship women's complex: balanced estrogen elimination, aromatase regulation and calm mood.","caution":"Overlaps heavily with FemGuard + Balance — do not run both. Green tea extract has a hepatotoxicity signal at concentrated doses; black cohosh has its own. Vitex is dopaminergic.","conditions":["Premenstrual syndrome"],"also":null},{"id":"xym_medcaps_dpo","brand":"Xymogen","name":"MedCaps DPO","target":"hepatic","base":"mixed","actives":"Hepatic Phase I and Phase II support — sulfation and glucuronidation cofactors","what":"Co-prescribed with a hormone regimen to optimise Phase I CYP450 clearance and Phase II conjugation of steroid hormones.","caution":"Driving hepatic clearance changes the clearance of everything else the patient takes, including their contraception and any narrow-therapeutic-index drug. Review the full medication list first.","conditions":[],"also":null},{"id":"xym_dhea_preg","brand":"Xymogen","name":"DHEA and Pregnenolone","target":"precursor","base":"hormone","actives":"Dehydroepiandrosterone and pregnenolone in several strengths","what":"Upstream adrenal and ovarian steroid support where a deficiency has been demonstrated.","caution":"Hormones. Do not start either on symptoms alone — measure first, monitor after, and check your prescribing scope.","conditions":[],"also":null},{"id":"klaire_womens_probiotic","brand":"Klaire Labs","name":"Ther-Biotic Women's Probiotic","target":"estrobolome","base":"probiotic","actives":"L. acidophilus, L. rhamnosus, L. gasseri, L. plantarum and bifidobacteria, 25 billion CFU","what":"Approaches hormonal balance through the estrobolome — the enteric bacteria that metabolise estrogens. Aims to suppress microbial beta-glucuronidase overactivity, and with it the deconjugation and reabsorption of estrogens already marked for excretion.","caution":"Avoid live probiotics in the immunocompromised, in anyone with a central venous catheter, and in acute pancreatitis — there are case reports of fungaemia and bacteraemia. The estrobolome model is well-founded in principle; that a given product shifts it measurably is not established.","conditions":[],"also":null},{"id":"klaire_target_b2","brand":"Klaire Labs","name":"Target b2","target":"estrobolome","base":"probiotic","actives":"Lactobacillus fermentum CECT5716","what":"Maintains healthy mammary duct microflora during lactation.","caution":"The strain is the evidence — CECT5716 specifically, studied in lactational mastitis. Do not substitute another L. fermentum and expect the same.","conditions":["Lactation support"],"also":null},{"id":"sh_dim_i3c","brand":"Seeking Health","name":"DIM + I3C","target":"phase12","base":"nutrient","actives":"Diindolylmethane, indole-3-carbinol, and Emothion S-acetyl-L-glutathione","what":"The glutathione is the point: it is there to neutralise the reactive estrogen quinone intermediates Phase I hydroxylation generates.","caution":"Pushing Phase I without Phase II capacity is how you generate those quinones in the first place — check methylation and sulfation status before driving hydroxylation hard. Not in pregnancy.","conditions":[],"also":null},{"id":"sh_calcium_d_glucarate","brand":"Seeking Health","name":"Calcium D-Glucarate","target":"phase12","base":"nutrient","actives":"Calcium D-glucarate","what":"Inhibits excessive beta-glucuronidase in the colon so that estrogens bound for biliary excretion are actually evacuated.","caution":"The same inhibition applies to any drug cleared by glucuronidation and enterohepatic recycling, oral contraceptives among them.","conditions":[],"also":null},{"id":"sh_comt_support","brand":"Seeking Health","name":"HomocysteX Plus and Liver Nutrients","target":"phase12","base":"nutrient","actives":"Active methyl donors — methylfolate, methylcobalamin, B6, and SAMe precursors","what":"COMT support: the methylation step that converts potentially genotoxic 4-hydroxyestrone to benign 4-methoxyestrone.","caution":"Methylfolate at high dose provokes anxiety, irritability and insomnia in a subset of patients — start low. Never give folate without B12 status: it masks a B12 deficiency while the neuropathy progresses.","conditions":[],"also":null},{"id":"gaia_womens_balance","brand":"Gaia Herbs","name":"Women's Balance","target":"luteal","base":"botanical","actives":"Vitex, black cohosh, red clover, St John's wort, dandelion, oats — organic liquid phyto-caps","what":"Whole-plant synergy for cycle transition and perimenopausal support.","caution":"St John's wort is the problem in this formula: a potent CYP3A4 inducer that causes oral contraceptive failure and breakthrough bleeding, raises serotonin syndrome risk with an SSRI or triptan, and reduces levels of anticoagulants, anticonvulsants, ciclosporin and antiretrovirals. Check the medication list before this one goes anywhere near a patient. Red clover is a phytoestrogen; black cohosh has its hepatic signal.","conditions":["Menopause","Premenstrual syndrome"],"also":null},{"id":"gaia_menopause_daynight","brand":"Gaia Herbs","name":"Menopause Support Daytime and Nighttime","target":"vasomotor","base":"botanical","actives":"Standardised black cohosh with passionflower and mimosa tree bark (Albizia julibrissin)","what":"Night sweats and sleep latency, split across a daytime and a nighttime formula.","caution":"Sedating at night — additive with any other sedative, and with alcohol. Black cohosh: rare hepatotoxicity.","conditions":["Menopause","Insomnia"],"also":null},{"id":"gaia_single_herbs","brand":"Gaia Herbs","name":"Single-herb phyto-caps — Vitex Berry, Black Cohosh, Maca Root","target":"luteal","base":"botanical","actives":"Standardised single botanicals: Vitex berry, black cohosh, and gelatinized maca root","what":"Single herbs where a blend would be guesswork — Vitex for pituitary and corpus luteum stimulation, black cohosh for vasomotor symptoms, gelatinized maca as an endocrine adaptogen.","caution":"Each carries its own caution: Vitex is dopaminergic, black cohosh has a hepatic signal, and maca is goitrogenic raw — gelatinized is the form to use. All three appear in the Herb Reference with their pregnancy and lactation ratings.","conditions":["Menopause","Premenstrual syndrome"],"also":null}]};
